#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# Notes captured here are for this setup only (which backend was smoke-tested
# against, the resulting *.pages.dev URL) — not consumed by the app, so kept
# out of frontend/.env or backend/.env.
ENV_FILE="scripts/.cloudflare-pages-setup.local"

TOTAL_STAGES=9

banner "Cloudflare Pages setup — issue #343"

say "Code-side work is already done and committed: frontend/wrangler.toml"
say "(project name, build output dir, Node version) is checked in, and the"
say "Vercel-only analytics packages/imports are removed. This wizard only"
say "covers the parts that need your Cloudflare account and GitHub access —"
say "creating the Pages project and confirming it builds and renders."
say ""
warn "The existing Vercel production deployment must stay untouched by all of this."

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Create the Cloudflare Pages project"
say "Two ways to do this — pick whichever you're more comfortable with."
step "Dashboard: Cloudflare dashboard → Workers & Pages → Create → Pages →"
step "  Connect to Git → authorize/select the allut/event-radar GitHub repo."
open_url "https://dash.cloudflare.com/?to=/:account/pages/new/provider/github"
note "OR, from the CLI instead of the dashboard:"
note "  cd frontend && npx wrangler login"
note "  npx wrangler pages project create event-radar"
note "(the project name 'event-radar' matches the 'name' in frontend/wrangler.toml)"
pause "Press Enter once the Pages project exists and is connected to the repo."

# ── Stage 2 ──────────────────────────────────────────────────────────────
stage "Build configuration (monorepo root)"
say "This repo is a monorepo — the SPA lives under frontend/, so the Pages"
say "project's build settings need to point there explicitly."
step "In the project's Settings → Builds & deployments → Build configuration, set:"
step "  Root directory:        frontend"
step "  Build command:         npm run build"
step "  Build output directory: dist"
note "These mirror frontend/wrangler.toml's pages_build_output_dir = \"dist\"."
note "wrangler.toml's own [build] command is a fallback for 'wrangler pages"
note "deploy' — the dashboard's own Build configuration is what actually runs"
note "on every git push, so set it there even if wrangler.toml already has it."
pause "Press Enter once root directory / build command / output directory are set."

# ── Stage 3 ──────────────────────────────────────────────────────────────
stage "Node version"
say "CI (.github/workflows/tests.yml) builds this frontend on Node 20 — Pages"
say "should match, so nothing works locally but breaks on a Cloudflare build."
step "In Settings → Environment variables (Production and Preview both), add:"
step "  NODE_VERSION = 20"
note "wrangler.toml already declares [vars] NODE_VERSION = \"20\", but confirm"
note "the dashboard picked it up under Environment variables — if the field is"
note "empty, add it there directly; the dashboard value wins either way."
pause "Press Enter once NODE_VERSION=20 is confirmed in the project's env vars."

# ── Stage 4 ──────────────────────────────────────────────────────────────
stage "Backend origin for smoke-testing"
say "There's no vercel.json-style /api rewrite on Cloudflare Pages yet — that's"
say "explicitly a later ticket. For THIS ticket, the acceptance bar is just"
say "'the app shell renders correctly', not working API calls. You do not need"
say "to make /api work for this preview to pass — skip straight to Stage 5 if"
say "you just want the shell smoke-test."
say ""
say "If you'd still like to eyeball real data loading against a backend,"
say "pick which one you're smoke-testing against (informational only —"
say "recorded below for your own reference, nothing reads this file):"
step "  A) https://event-radar-api.onrender.com (existing Render free tier)"
step "  B) the new Frankfurt backend from issue #342, if it's deployed"
ask CF_SMOKE_BACKEND "Which backend are you smoke-testing against? (A/B/skip):"
write_env CF_SMOKE_BACKEND "$CF_SMOKE_BACKEND"
note "Recorded for reference only — no code change happens here."

# ── Stage 5 ──────────────────────────────────────────────────────────────
stage "Trigger a build on a throwaway/preview branch"
say "Do NOT push to master/whatever branch Cloudflare treats as production —"
say "the acceptance criteria only calls for a preview-branch build."
step "Push any existing throwaway branch (or create one, e.g. 'cf-pages-smoke-test')"
step "  to GitHub — Cloudflare Pages auto-builds every branch it's connected to"
step "  as a Preview deployment, distinct from its Production deployment."
step "Watch the build in the dashboard: Workers & Pages → event-radar → the new deployment."
pause "Press Enter once the preview build finishes (success or failure)."
if ! confirm "Did the build succeed?"; then
  warn "Check the build log in the dashboard for the failing step (npm install /"
  warn "tsc / vite build) before continuing — re-run this wizard from Stage 2 once fixed."
fi

# ── Stage 6 ──────────────────────────────────────────────────────────────
stage "Open the preview URL and confirm the app shell renders"
step "From the deployment's detail page, copy its unique *.pages.dev preview URL."
ask CF_PAGES_PREVIEW_URL "Paste the preview *.pages.dev URL:"
write_env CF_PAGES_PREVIEW_URL "$CF_PAGES_PREVIEW_URL"
open_url "$CF_PAGES_PREVIEW_URL"
step "Confirm the page loads the app shell (Landing page, no blank white screen,"
step "  no console error about a missing asset/chunk)."
step "Open the browser's Network tab and confirm /api/* calls return errors"
step "  (expected — no backend proxy wired yet) rather than the whole page failing to load."
pause "Press Enter once you've confirmed the shell renders."

# ── Stage 7 ──────────────────────────────────────────────────────────────
stage "Confirm Google Analytics still fires (Vercel-only analytics were removed)"
say "@vercel/analytics and @vercel/speed-insights were removed from App.tsx —"
say "this stage confirms the first-party GoogleAnalytics wiring is unaffected."
step "Open GA4 → Admin → DebugView for this property, OR just open the preview"
step "  URL's Network tab and filter for a request to google-analytics.com/g/collect."
open_url "https://analytics.google.com/analytics/web/"
step "Reload the preview URL from Stage 6 and wait a few seconds (there's a"
step "  short deliberate delay before the pageview fires — see PAGEVIEW_TRACK_DELAY_MS"
step "  in frontend/src/constants.ts)."
step "Confirm a pageview shows up in DebugView, or a collect request fires in Network."
pause "Press Enter once you've confirmed a GA pageview fired."

# ── Stage 8 ──────────────────────────────────────────────────────────────
stage "Confirm the existing Vercel production deployment is untouched"
say "None of this should have touched Vercel — this is just a sanity check."
step "Open the current production domain (the one Vercel serves) and confirm"
step "  it still loads normally, on the same commit it was on before this ticket."
ask CF_PROD_VERCEL_URL "Paste the production Vercel URL you checked:"
write_env CF_PROD_VERCEL_URL "$CF_PROD_VERCEL_URL"
open_url "$CF_PROD_VERCEL_URL"
pause "Press Enter once you've confirmed Vercel production is still serving normally."

# ── Stage 9 ──────────────────────────────────────────────────────────────
stage "Acceptance criteria recap (issue #343)"
say "Run through the issue's checklist one more time before closing it out:"
step "[ ] Cloudflare Pages project created, connected to this repo, builds on a preview branch"
step "[ ] SPA reachable at its *.pages.dev URL, app shell renders correctly"
step "[ ] @vercel/analytics + @vercel/speed-insights removed from App.tsx/package.json (done in code, already committed)"
step "[ ] GoogleAnalytics / maskAnalyticsUrl confirmed unaffected — pageview fires"
step "[ ] wrangler.toml checked into the repo (done, already committed)"
step "[ ] Existing Vercel deployment untouched and still serving production"
step "[ ] npm run build / type-check / test pass with Vercel analytics packages removed (done, already verified)"
if confirm "Are all boxes above checked?"; then
  say "Nice — issue #343 is ready to close out."
else
  warn "Note which ones aren't checked yet and go finish those before closing the issue."
fi

finish
